-- Gameobject spawns for Strand of the Ancients (map 607) - gates, doors and siege
-- related objects. RetailCore ships the map with no gameobjects.
-- Source: TDB_full_world_1027.24051_2024_05_11.sql (official TrinityCore TDB)
-- guids are taken from a reserved range, the DELETE keeps this file re-runnable.

DELETE FROM `gameobject` WHERE `guid` BETWEEN 410000000000000001 AND 410000000000000244;

